code_snippets.typescript_fastapi_request_body_snippet:

// Relevant part of the request body for POST /generate-schedule
interface GenerateScheduleRequestBody {
  course_id: number;
  exam_date: string; // ISO format 'YYYY-MM-DD'
  topics: Array<{ title: string, description?: string }>; // From previous wizard step
  user_preferences: {
    hours_per_week: number;
    study_weekends: boolean; // Example preference
    // Add other preferences as needed (e.g., break times, study intensity)
  };
}

code_snippets.python_fastapi_endpoint_snippet:
# FastAPI Backend - relevant part of /generate-schedule endpoint from fastapi import APIRouter, Depends, HTTPException from pydantic import BaseModel from typing import List, Optional, Dict import datetime
router = APIRouter()
class UserPreferences(BaseModel): hours_per_week: int study_weekends: bool = False # Default to false if not provided
class GenerateScheduleRequestBody(BaseModel): course_id: int exam_date: datetime.date topics: List[dict] # Simplified for snippet, actual Topic model is more detailed user_preferences: UserPreferences
@router.post("/generate-schedule") async def generate_schedule(request: GenerateScheduleRequestBody, current_user: Dict = Depends(get_current_user_from_jwt)): # Access preferences: request.user_preferences.hours_per_week, request.user_preferences.study_weekends # ... scheduling logic ... return {"success": True, "session_count": 50}

